def inside(px,py,poly):
    ins=False
    for i,(x1,y1) in enumerate(poly):
        x2,y2=poly[(i+1)%len(poly)]
        if ((y1>py)!=(y2>py)) and px < (x2-x1)*(py-y1)/(y2-y1)+x1: ins=not ins
    return ins
